const body = $input.first().json.body || $input.first().json;
const message = body.message || body.channel_post || {};
const from = message.from || {};
const chat = message.chat || {};

if (!message.text && !message.voice) {
  return [{ json: { ignore: true, reason: 'No text or voice message' } }];
}

return [{
  json: {
    ignore: false,
    telegram_id: String(from.id || chat.id),
    chat_id: String(chat.id),
    first_name: from.first_name || '',
    last_name: from.last_name || '',
    username: from.username || '',
    text: (message.text || '').trim(),
    message_id: message.message_id,
    date: message.date,
    is_voice: !!message.voice
  }
}];

const snapshot = $input.first().json;
const lead = snapshot.lead;
const qual = snapshot.qualification || {};
const raw = qual.raw_answers || {};
const chatData = $('Normalizar Payload Telegram').first().json;
const userText = chatData.text || '';
const state = lead.current_state;

const isAgente1 = ['NEW_LEAD', 'QUALIFYING', 'WARM', 'PARTIAL'].includes(state);

let activeQuestion = 'P1';
if (raw.P4) {
  activeQuestion = 'P4';
} else if (raw.P3_INVESTMENT) {
  activeQuestion = 'P4';
} else if (raw.P3_AUTHORITY) {
  activeQuestion = 'P3_INVESTMENT';
} else if (raw.P2) {
  activeQuestion = 'P3_AUTHORITY';
} else if (raw.P1) {
  activeQuestion = 'P2';
}

// Construir System Prompt blindado para Agente 1 (Gemini)
const systemPrompt = `Eres el asistente conversacional oficial de Fernández Briceño Studio (FBS), un estudio de diseño y branding estratégico en Chile.
Tu misión es guiar al prospecto en un proceso de calificación de 4 preguntas cortas (P1 a P4), de forma natural, humana y profesional.

REGLAS INVIOLABLES DE ROL Y TONO:
1. NUNCA te salgas del guion ni inventes servicios, precios ni metodologías fuera de lo estipulado.
2. Mensajes SIEMPRE cortos: máximo 2 a 3 líneas por mensaje. Nadie escribe párrafos en mensajería.
3. Empatía primero: haz una micro-reacción corta a lo que el prospecto acaba de decir antes de hacer la siguiente pregunta (ej: "Ya, tiene sentido.", "Perfecto, eso ayuda a entender el panorama.", "Ok, anotado.", "Entiendo — pasa más de lo que crees."). ROTA siempre las frases, nunca repitas la misma dos veces.
4. Cero lenguaje robótico: PROHIBIDO decir "procesando", "gracias por responder", "consulta registrada".
5. Si el prospecto pregunta si eres un bot, responde honesto: "Soy un asistente del equipo — te ayudo a agilizar esto antes de pasarte con una persona real."
6. El piso de inversión oficial de FBS para proyectos de marca es $1.200.000 CLP.
7. Si el prospecto desvía la conversación o pregunta precios antes de P3, responde en 1 línea corta y reencauza de inmediato hacia la pregunta pendiente.

ESTADO ACTUAL DEL PROSPECTO:
- Nombre: ${lead.first_name || 'Prospecto'}
- Estado CRM: ${state}
- Pregunta a procesar o formular: ${activeQuestion}
- Historial previo capturado: ${JSON.stringify(raw)}

MENSAJE RECIBIDO DEL PROSPECTO:
"${userText}"

Debes responder OBLIGATORIAMENTE con un objeto JSON válido con este formato:
{
  "parsed_answer": "Texto limpio que responde a ${activeQuestion} para almacenar en el CRM",
  "bot_reply": "Tu mensaje conversacional exacto y humanizado para enviar al usuario en Telegram"
}`;

const service = qual.service_needed || 'tu proyecto de marca';
const calLink = `https://cal.com/fbs-studio/consulta-30min?lead_id=${lead.id}`;
const formLink = `https://fbs.studio/precall/${lead.id}`;

let agente2Reply = '';
if (state === 'QUALIFIED') {
  agente2Reply = `¡Hola! Soy parte del equipo de coordinación de FBS. Vi que conversaste con el equipo sobre ${service} y el encaje es excelente. Vamos a coordinar la videollamada estratégica de 30 min (sin costo): puedes elegir el día y hora que mejor te acomode en este link: ${calLink}`;
} else if (state === 'CONSULTATION_PENDING') {
  agente2Reply = `Tu cita ya está en agenda. Por favor completa este breve formulario de 5 minutos antes de la reunión para enfocar la llamada directamente en estrategia: ${formLink}`;
} else {
  agente2Reply = `Gracias por tu mensaje. El equipo ya tiene tu caso registrado y te contactaremos a la brevedad.`;
}

return [{
  json: {
    is_agente_1: isAgente1,
    lead_id: lead.id,
    chat_id: chatData.chat_id,
    active_question: activeQuestion,
    user_answer: userText,
    system_prompt: systemPrompt,
    agente2_reply: agente2Reply
  }
}];

let rawText = '';
const geminiOut = $input.first().json;

if (geminiOut.content?.parts?.[0]?.text) {
  rawText = geminiOut.content.parts[0].text;
} else if (typeof geminiOut === 'string') {
  rawText = geminiOut;
} else if (geminiOut.bot_reply) {
  return [{ json: geminiOut }];
}

let parsed = {};
try {
  const clean = rawText.replace(/```(?:json)?\s*([\s\S]*?)\s*```/i, '$1').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  parsed = { parsed_answer: $('Preparar Enrutamiento y Prompt').first().json.user_answer, bot_reply: rawText };
}

const routeData = $('Preparar Enrutamiento y Prompt').first().json;

return [{
  json: {
    lead_id: routeData.lead_id,
    chat_id: routeData.chat_id,
    active_question: routeData.active_question,
    parsed_answer: parsed.parsed_answer || routeData.user_answer,
    bot_reply: parsed.bot_reply || rawText
  }
}];

const geminiData = $('Procesar Salida de Gemini').first().json;
const apiData = $input.first().json;

// El bot_reply de Gemini humaniza la interacción mientras que la API garantiza la lógica
const finalReply = geminiData.bot_reply || apiData.message_text;

return [{
  json: {
    chat_id: geminiData.chat_id,
    reply_text: finalReply,
    lead_id: geminiData.lead_id
  }
}];

const item = $input.first().json;
return [{
  json: {
    chat_id: item.chat_id,
    reply_text: item.agente2_reply,
    lead_id: item.lead_id
  }
}];
